                    ),
                ],
            },
        },
        validate.get("streamingData"),
        validate.union_get("hlsManifestUrl", "formats", "adaptiveFormats"),
    )
    hls_manifest, formats, adaptive_formats = schema.validate(data)
    return hls_manifest, formats or [], adaptive_formats or []

